using Cosmos.Application.Abstractions.Persistence;
using Cosmos.Application.PurchaseExpense;
using Cosmos.Domain.PurchaseExpense;
using FluentValidation;

namespace Cosmos.Application.Validators;

public sealed class PurchaseLineValidator : AbstractValidator<PurchaseLineRequest> { public PurchaseLineValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.ItemId).GreaterThan(0).MustAsync(r.ItemExistsAsync).WithMessage("Item was not found."); RuleFor(x=>x.Quantity).GreaterThan(0); RuleFor(x=>x.PurchasePrice).GreaterThanOrEqualTo(0); RuleFor(x=>x.DiscountPercentage).InclusiveBetween(0,100); RuleFor(x=>x.DiscountAmount).GreaterThanOrEqualTo(0); RuleFor(x=>x.TaxPercentage).GreaterThanOrEqualTo(0); } }
public sealed class CreatePurchaseBillValidator : AbstractValidator<CreatePurchaseBillRequest> { public CreatePurchaseBillValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.SupplierId).NotEmpty().MustAsync(r.SupplierExistsAsync).WithMessage("Supplier was not found."); RuleFor(x=>x.DueDate).GreaterThanOrEqualTo(x=>x.BillDate).When(x=>x.DueDate.HasValue); RuleFor(x=>x.Items).NotEmpty(); RuleForEach(x=>x.Items).SetValidator(new PurchaseLineValidator(r)); RuleFor(x=>x.PaidAmount).GreaterThanOrEqualTo(0); RuleFor(x=>x.PaymentType).Must(x=>Enum.IsDefined(typeof(PurchasePaymentMode),x)); RuleFor(x=>x.Notes).MaximumLength(1000); } }
public sealed class UpdatePurchaseBillValidator : AbstractValidator<UpdatePurchaseBillRequest> { public UpdatePurchaseBillValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.SupplierId).NotEmpty().MustAsync(r.SupplierExistsAsync).WithMessage("Supplier was not found."); RuleFor(x=>x.DueDate).GreaterThanOrEqualTo(x=>x.BillDate).When(x=>x.DueDate.HasValue); RuleFor(x=>x.Items).NotEmpty(); RuleForEach(x=>x.Items).SetValidator(new PurchaseLineValidator(r)); RuleFor(x=>x.PaidAmount).GreaterThanOrEqualTo(0); RuleFor(x=>x.PaymentType).Must(x=>Enum.IsDefined(typeof(PurchasePaymentMode),x)); RuleFor(x=>x.Notes).MaximumLength(1000); } }
public sealed class CreateSupplierPaymentValidator : AbstractValidator<CreateSupplierPaymentRequest> { public CreateSupplierPaymentValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.SupplierId).NotEmpty().MustAsync(r.SupplierExistsAsync); RuleFor(x=>x.Amount).GreaterThan(0); RuleFor(x=>x.PaymentMode).Must(x=>Enum.IsDefined(typeof(PurchasePaymentMode),x)); RuleForEach(x=>x.Allocations).ChildRules(a=>a.RuleFor(x=>x.AllocatedAmount).GreaterThan(0)); RuleFor(x=>x).Must(x=>(x.Allocations?.Sum(a=>a.AllocatedAmount)??0)<=x.Amount).WithMessage("Allocated amount cannot exceed payment amount."); } }
public sealed class CreateExpenseCategoryValidator : AbstractValidator<CreateExpenseCategoryRequest> { public CreateExpenseCategoryValidator() { RuleFor(x=>x.Name).NotEmpty().MaximumLength(150); RuleFor(x=>x.Description).MaximumLength(500); } }
public sealed class CreateExpenseValidator : AbstractValidator<CreateExpenseRequest> { public CreateExpenseValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.CategoryId).GreaterThan(0).MustAsync(r.ExpenseCategoryExistsAsync); RuleFor(x=>x.Amount).GreaterThan(0); RuleFor(x=>x.TaxAmount).GreaterThanOrEqualTo(0); RuleFor(x=>x.PaymentMode).Must(x=>Enum.IsDefined(typeof(PurchasePaymentMode),x)); } }
public sealed class CreatePurchaseOrderValidator : AbstractValidator<CreatePurchaseOrderRequest> { public CreatePurchaseOrderValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.SupplierId).NotEmpty().MustAsync(r.SupplierExistsAsync); RuleFor(x=>x.ExpectedDeliveryDate).GreaterThanOrEqualTo(x=>x.OrderDate).When(x=>x.ExpectedDeliveryDate.HasValue); RuleFor(x=>x.Items).NotEmpty(); RuleForEach(x=>x.Items).SetValidator(new PurchaseLineValidator(r)); } }
public sealed class CreatePurchaseReturnValidator : AbstractValidator<CreatePurchaseReturnRequest> { public CreatePurchaseReturnValidator(IPurchaseExpenseRepository r) { RuleFor(x=>x.SupplierId).NotEmpty().MustAsync(r.SupplierExistsAsync); RuleFor(x=>x.Items).NotEmpty(); RuleForEach(x=>x.Items).SetValidator(new PurchaseLineValidator(r)); } }
public sealed class PurchaseBillListValidator : AbstractValidator<PurchaseBillListQuery> { public PurchaseBillListValidator(){RuleFor(x=>x.PageNumber).GreaterThan(0);RuleFor(x=>x.PageSize).InclusiveBetween(1,200);RuleFor(x=>x.SortDirection).Must(x=>string.Equals(x,"ASC",StringComparison.OrdinalIgnoreCase)||string.Equals(x,"DESC",StringComparison.OrdinalIgnoreCase));RuleFor(x=>x.ToDate).GreaterThanOrEqualTo(x=>x.FromDate).When(x=>x.FromDate.HasValue&&x.ToDate.HasValue);} }
